import React from 'react';
import type { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

//#region Typings
/** Accepted properties for the Select Suffix */
export type SelectV2SuffixProps = PropsWithChildren<unknown> &
  StylingProps &
  DataTestId;
//#endregion

/**
 * Typeguard function that will check if a React.Node is a SelectV2.Suffix
 * @internal
 */
export function _isSelectV2SuffixElement(
  child: React.ReactNode,
): child is React.ReactElement<SelectV2SuffixProps> {
  if (isElement(child) && child.type === SelectV2Suffix) {
    return true;
  }
  return false;
}

/**
 * The `SelectV2.Suffix` component allows you to specify any content, that should
 * be prefixed in the trigger element. The `SelectV2.Suffix` component is only valid
 * within the `SelectV2.Trigger` and `SelectV2.Option` element.
 * @example
 * ```tsx
 * <SelectV2.DisplayValue>
 *   <SelectV2.Suffix>
 *     <WhatsNewIcon />
 *   </SelectV2.Suffix>
 * </SelectV2.DisplayValue>
 * ```
 */
export function SelectV2Suffix(props: SelectV2SuffixProps) {
  return null;
}

SelectV2Suffix.displayName = 'Select.Suffix';
